package com.abhishek.ecommerce.order;
import com.abhishek.ecommerce.common.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/orders")public class OrderController{record ItemRequest(@NotNull UUID productId,@Min(1)int quantity){}record CreateOrder(@NotEmpty List<@Valid ItemRequest>items){}final OrderRepository repo;final ProductClient products;final KafkaTemplate<String,DomainEvent>kafka;OrderController(OrderRepository r,ProductClient p,KafkaTemplate<String,DomainEvent>k){repo=r;products=p;kafka=k;}@PostMapping ResponseEntity<OrderEntity>create(@RequestHeader("X-User-Id")String user,@Valid @RequestBody CreateOrder req){OrderEntity o=new OrderEntity();o.setUserId(user);o.setStatus(OrderStatus.PAYMENT_PENDING);BigDecimal total=BigDecimal.ZERO;for(ItemRequest i:req.items()){var p=products.get(i.productId());if(!p.active())throw new ResponseStatusException(HttpStatus.CONFLICT,"Product unavailable");products.reserve(i.productId(),i.quantity());OrderItem x=new OrderItem();x.setProductId(i.productId().toString());x.setQuantity(i.quantity());x.setUnitPrice(p.price());o.getItems().add(x);total=total.add(p.price().multiply(BigDecimal.valueOf(i.quantity())));}o.setTotal(total);repo.save(o);kafka.send("order-events",new DomainEvent(EventType.ORDER_CREATED,UUID.randomUUID().toString(),o.getId().toString(),user,total.toPlainString(),Instant.now()));return ResponseEntity.status(201).body(o);}@GetMapping List<OrderEntity>history(@RequestHeader("X-User-Id")String user){return repo.findByUserId(user);}@GetMapping("/{id}")OrderEntity one(@RequestHeader("X-User-Id")String user,@PathVariable UUID id){OrderEntity o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));if(!o.getUserId().equals(user))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return o;}@PostMapping("/{id}/cancel")OrderEntity cancel(@RequestHeader("X-User-Id")String user,@PathVariable UUID id){OrderEntity o=one(user,id);if(o.getStatus()==OrderStatus.PAID||o.getStatus()==OrderStatus.PAYMENT_PENDING){o.setStatus(OrderStatus.CANCELLED);return repo.save(o);}throw new ResponseStatusException(HttpStatus.CONFLICT,"Order cannot be cancelled");}@KafkaListener(topics="payment-events",groupId="order-service")void payment(DomainEvent e){repo.findById(UUID.fromString(e.aggregateId())).ifPresent(o->{o.setStatus(e.eventType()==EventType.PAYMENT_SUCCESS?OrderStatus.PAID:OrderStatus.PAYMENT_FAILED);repo.save(o);});}}